<script setup>
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, errorMessage, localTime } from './api'
import { personalGroups, employmentFields, displayValue } from './employee-fields'
const people=ref([]),page=ref(1),last=ref(1),search=ref(''),selected=ref(null),record=ref(null),busy=ref(false),error=ref(''),message=ref(''),markReviewed=ref(false),employment=reactive({});let generation=0
async function load(){busy.value=true;error.value='';try{const {data}=await api.get('/api/admin/personnel',{params:{page:page.value,search:search.value}});people.value=data.data;last.value=data.last_page}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function choose(person){const current=++generation;selected.value=person;record.value=null;busy.value=true;error.value='';message.value='';markReviewed.value=false;try{const {data}=await api.get('/api/admin/personnel/'+person.id);if(current!==generation)return;record.value=data.profile;Object.keys(employment).forEach(k=>delete employment[k]);Object.assign(employment,data.profile.employment)}catch(err){if(current===generation)error.value=errorMessage(err)}finally{if(current===generation)busy.value=false}}
async function save(){busy.value=true;error.value='';message.value='';try{const {data}=await api.put('/api/admin/personnel/'+selected.value.id,{employment,mark_reviewed:markReviewed.value,expected_revision:record.value.revision});record.value=data.profile;markReviewed.value=false;message.value='Employment record saved.'}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
onMounted(load);onUnmounted(()=>generation++)
</script>
<template><section><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><template v-if="!selected"><form class="filter-bar" @submit.prevent="page=1;load()"><label>Find an employee<input v-model.trim="search" maxlength="120" placeholder="Name or email"></label><button :disabled="busy">Search</button></form><section class="card table-card"><table><thead><tr><th>Employee</th><th>Account</th><th>Personnel record</th></tr></thead><tbody><tr v-for="person in people" :key="person.id"><td><strong>{{person.name}}</strong><small>{{person.email}}</small></td><td>{{person.enabled?'Enabled':'Disabled'}}</td><td><button class="small-button" :disabled="busy" @click="choose(person)">Open profile</button></td></tr><tr v-if="!people.length"><td colspan="3" class="empty-cell">{{busy?'Loading…':'No matching employees.'}}</td></tr></tbody></table></section><div class="pagination"><span>Page {{page}} of {{last}}</span><div><button :disabled="busy || page<=1" @click="page--;load()">Previous</button><button :disabled="busy || page>=last" @click="page++;load()">Next</button></div></div></template><template v-else><div class="heading-actions" style="margin-bottom:20px"><button :disabled="busy" @click="selected=null;record=null;generation++">← All employees</button><button :disabled="busy" @click="choose(selected)">Reload record</button></div><p v-if="busy && !record" class="card">Loading personnel record…</p><template v-if="record"><section class="card" style="margin-bottom:20px"><h2>{{record.name}}</h2><p>{{record.email}} · {{record.phone || 'No phone provided'}} · {{record.location || 'Location not provided'}}</p><span class="pill" :class="record.reviewed_at?'green':'amber'">{{record.reviewed_at?'HR reviewed '+localTime(record.reviewed_at):'Awaiting HR review'}}</span><p class="employee-caption">Review confirms that HR has checked this personnel record. It does not verify identity documents. Employee edits clear this review status.</p></section><div class="personnel-admin-grid"><div><section v-for="group in personalGroups" :key="group.title" class="card" style="margin-bottom:20px"><h2>{{group.title}}</h2><dl class="personnel-facts"><div v-for="field in group.fields" :key="field[0]" :class="{'personnel-wide':field[2]==='textarea'}"><dt>{{field[1]}}</dt><dd>{{displayValue(record.personal[field[0]])}}</dd></div></dl></section></div><form class="card" @submit.prevent="save"><h2>Employment details</h2><p class="muted small">These fields are read-only in the employee workspace.</p><label v-for="field in employmentFields" :key="field[0]">{{field[1]}}<select v-if="field[2]==='select'" v-model="employment[field[0]]"><option value="">Not specified</option><option v-for="option in field[3]" :key="option" :value="option">{{displayValue(option)}}</option></select><input v-else v-model.trim="employment[field[0]]" :type="field[2] || 'text'" :maxlength="field[0]==='employee_code'?60:field[0]==='office'?150:120"></label><label class="check-label"><input v-model="markReviewed" type="checkbox">I have reviewed this personnel record</label><p class="small muted">Employment status is an HR record; it does not enable or disable the employee's login.</p><button class="primary full" :disabled="busy">Save employment details</button></form></div></template></template></section></template>
